/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Tenant } from 'app/features/identity/tenant/model/tenant.model';
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'tenant-view-disable-selection-action', standalone: false, template: '' })
export class TenantViewDisableSelectionActionComponent extends ConfirmSelectionAction<Tenant> {
  readonly name = 'disableSelection';
  protected readonly scope = 'identity/tenant';
  protected readonly repository = inject(TenantRepository);

  protected override appliesTo(items: Tenant[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: Tenant[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
